            x75 = x26*x73 - x31*x73 + 3.0_wp*x74
            x76 = d_a(2)*x66 - d_a(2)*x71 - x67*x69 + x69*x72 + x75
            x77 = d_a(3)*x68
            x78 = d_a(1)*d_a(3)
            x79 = 9.0_wp*x78
            x80 = d_a(1)*x46
            x81 = x26*x79 - x31*x79 + 3.0_wp*x80
            x82 = d_a(3)*x66 - d_a(3)*x71 - x67*x77 + x72*x77 + x81
            x83 = (d_a(1)*d_a(1)*d_a(1)*d_a(1))
            x84 = x6*x83
            x85 = 18.0_wp*x0
            x86 = 15.0_wp*x83
            x87 = -3.0_wp*x10 + 3.0_wp*x19
            x88 = d_a(2)*d_a(3)
            x89 = 15.0_wp*x67
            x90 = x0*x88
            x91 = x6*x65
            x92 = x0*x91
            x93 = x6*x70
            x94 = 15.0_wp*x72
            x95 = -x34*x88 + x36*x88 + x47 + x88*x92 - x89*x90 - x90*x93 + x90*x94
            x96 = x0*x1
            x97 = -x10
            x98 = x19 + x33 - x35 + x37 + x97
            x99 = x50 - x51 + x52
            x100 = x1*x92 - x89*x96 - x93*x96 + x94*x96 + x98 + x99
            x101 = x0*x2
            x102 = x55 - x56 + x57
            x103 = -x101*x89 - x101*x93 + x101*x94 + x102 + x2*x92 + x98
            x104 = d_a(1)*x91
            x105 = d_a(1)*x59
            x106 = x104*x59 - x105*x89 - x105*x93 + x105*x94 + x75
            x107 = x1*x78
            x108 = d_a(3)*x1*x104 - x107*x89 - x107*x93 + x107*x94 - x34*x78 + x36*x78 + x80
            x109 = x2*x44
            x110 = d_a(2)*x104*x2 - x109*x89 - x109*x93 + x109*x94 + x45 - x48 + x74
            x111 = d_a(1)*x63
            x112 = x104*x63 - x111*x89 - x111*x93 + x111*x94 + x81
            x113 = d_a(3)*x59
            x114 = 9.0_wp*x88
            x115 = x114*x26 - x114*x31 + 3.0_wp*x47
            x116 = -x113*x89 + x113*x91 - x113*x93 + x113*x94 + x115
            x117 = (d_a(2)*d_a(2)*d_a(2)*d_a(2))
            x118 = 18.0_wp*x1
            x119 = 15.0_wp*x117
            x120 = x1*x2
            x121 = x102 - x120*x89 + x120*x91 - x120*x93 + x120*x94 + x19 + x97 + x99
            x122 = d_a(2)*x63
            x123 = x115 - x122*x89 + x122*x91 - x122*x93 + x122*x94
            x124 = (d_a(3)*d_a(3)*d_a(3)*d_a(3))
            x125 = 18.0_wp*x2
            x126 = 15.0_wp*x124
            tg0 = tg0 + (-d_a(1)*v_a(1)*x8 - d_a(2)*v_a(2)*x8 - d_a(3)*v_a(3)*x8)
            tg1_r(1) = tg1_r(1) + (-v_a(1)*(-x0*x10 + x0*x19 + x8) - v_a(2)*x15 - v_a(3)*x17)
            tg1_r(2) = tg1_r(2) + (-v_a(1)*x15 - v_a(2)*(-x1*x10 + x1*x19 + x8) - v_a(3)*x20)
            tg1_r(3) = tg1_r(3) + (-v_a(1)*x17 - v_a(2)*x20 - v_a(3)*(-x10*x2 + x19*x2 + x8))
            tg2_rr(1, 1) = &
               tg2_rr(1, 1) + (-v_a(1)*(-3.0_wp*x21 + 3.0_wp*x22 + x24*x26 - x24*x31 + x27*x29) - &
               v_a(2)*x40 - v_a(3)*x43)
            t_tg2_rr_01 = -v_a(1)*x40 - v_a(2)*x54 - v_a(3)*x49
            tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
            tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
            t_tg2_rr_02 = -v_a(1)*x43 - v_a(2)*x49 - v_a(3)*x58
            tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
            tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
            tg2_rr(2, 2) = &
               tg2_rr(2, 2) + (-v_a(1)*x54 - v_a(2)*(-3.0_wp*x11 + x26*x60 - x31*x60 + x32*x59 + &
               3.0_wp*x38) - v_a(3)*x61)
            t_tg2_rr_12 = -v_a(1)*x49 - v_a(2)*x61 - v_a(3)*x62
            tg2_rr(2, 3) = tg2_rr(2, 3) + t_tg2_rr_12
            tg2_rr(3, 2) = tg2_rr(3, 2) + t_tg2_rr_12
            tg2_rr(3, 3) = &
               tg2_rr(3, 3) + (-v_a(1)*x58 - v_a(2)*x62 - v_a(3)*(-3.0_wp*x16 + x26*x64 - x31*x64 &
               + x32*x63 + 3.0_wp*x41))
            tg3_rrr(1, 1, 1) = &
               tg3_rrr(1, 1, 1) + (-v_a(1)*(x26*x85 - x31*x85 + 6.0_wp*x33 + x65*x84 - x67*x86 - &
               x70*x84 + x72*x86 + x87) - v_a(2)*x76 - v_a(3)*x82)
            t_tg3_rrr_001 = -v_a(1)*x76 - v_a(2)*x100 - v_a(3)*x95
            tg3_rrr(1, 1, 2) = tg3_rrr(1, 1, 2) + t_tg3_rrr_001
            tg3_rrr(1, 2, 1) = tg3_rrr(1, 2, 1) + t_tg3_rrr_001
            tg3_rrr(2, 1, 1) = tg3_rrr(2, 1, 1) + t_tg3_rrr_001
            t_tg3_rrr_002 = -v_a(1)*x82 - v_a(2)*x95 - v_a(3)*x103
            tg3_rrr(1, 1, 3) = tg3_rrr(1, 1, 3) + t_tg3_rrr_002
            tg3_rrr(1, 3, 1) = tg3_rrr(1, 3, 1) + t_tg3_rrr_002
            tg3_rrr(3, 1, 1) = tg3_rrr(3, 1, 1) + t_tg3_rrr_002
            t_tg3_rrr_011 = -v_a(1)*x100 - v_a(2)*x106 - v_a(3)*x108
            tg3_rrr(1, 2, 2) = tg3_rrr(1, 2, 2) + t_tg3_rrr_011
            tg3_rrr(2, 1, 2) = tg3_rrr(2, 1, 2) + t_tg3_rrr_011
            tg3_rrr(2, 2, 1) = tg3_rrr(2, 2, 1) + t_tg3_rrr_011
            t_tg3_rrr_012 = -v_a(1)*x95 - v_a(2)*x108 - v_a(3)*x110
            tg3_rrr(1, 2, 3) = tg3_rrr(1, 2, 3) + t_tg3_rrr_012
            tg3_rrr(1, 3, 2) = tg3_rrr(1, 3, 2) + t_tg3_rrr_012
            tg3_rrr(2, 1, 3) = tg3_rrr(2, 1, 3) + t_tg3_rrr_012
            tg3_rrr(2, 3, 1) = tg3_rrr(2, 3, 1) + t_tg3_rrr_012
            tg3_rrr(3, 1, 2) = tg3_rrr(3, 1, 2) + t_tg3_rrr_012
            tg3_rrr(3, 2, 1) = tg3_rrr(3, 2, 1) + t_tg3_rrr_012
            t_tg3_rrr_022 = -v_a(1)*x103 - v_a(2)*x110 - v_a(3)*x112
            tg3_rrr(1, 3, 3) = tg3_rrr(1, 3, 3) + t_tg3_rrr_022
            tg3_rrr(3, 1, 3) = tg3_rrr(3, 1, 3) + t_tg3_rrr_022
            tg3_rrr(3, 3, 1) = tg3_rrr(3, 3, 1) + t_tg3_rrr_022
            tg3_rrr(2, 2, 2) = &
               tg3_rrr(2, 2, 2) + (-v_a(1)*x106 - v_a(2)*(x117*x91 - x117*x93 + x118*x26 - &
               x118*x31 - x119*x67 + x119*x72 + 6.0_wp*x50 + x87) - v_a(3)*x116)
            t_tg3_rrr_112 = -v_a(1)*x108 - v_a(2)*x116 - v_a(3)*x121
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = -v_a(1)*x110 - v_a(2)*x121 - v_a(3)*x123
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = &
               tg3_rrr(3, 3, 3) + (-v_a(1)*x112 - v_a(2)*x123 - v_a(3)*(x124*x91 - x124*x93 + &
               x125*x26 - x125*x31 - x126*x67 + x126*x72 + 6.0_wp*x55 + x87))
         end block
      end select

   end subroutine cfc_atomic_tangent_eval

   pure module subroutine cfc_pair_tangent_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                         v_a, v_b, max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Nuclear displacement direction of atom a
      real(wp), intent(in) :: v_a(3)
      !> Nuclear displacement direction of atom b
      real(wp), intent(in) :: v_b(3)
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A v_A . d/dr_A of the order-0 spatial derivative
      real(wp), intent(inout) :: tg0
      !> sum_A v_A . d/dr_A of the order-1 spatial derivative
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A v_A . d/dr_A of the order-2 spatial derivative
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A v_A . d/dr_A of the order-3 spatial derivative
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_pair_tangent_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end .or. sg_b >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               g_b(0) = fj0
               g_b(1) = a2*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               x0 = d_b(1)*g_a(0)
               x1 = 1.0_wp/R_a
               x2 = 1.0_wp/R_b
               x3 = x1*x2
               x4 = -x3*(d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)) + 1.0_wp
               x5 = 4.0_wp*c_par*x3*(x4*x4*x4)
               x6 = g_b(0)*x5
               x7 = d_a(1)*g_b(0)
               x8 = c_par*(x4*x4*x4*x4)
               x9 = g_a(1)*x1*x8/sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
               x10 = g_a(0)*x6
               x11 = g_b(0)*x9
               x12 = g_b(1)*x2*x8/sqrt(((d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))))
               x13 = g_a(0)*x12
               tg0 = &
                  tg0 + (-v_a(1)*(-x0*x6 + x7*x9) - v_a(2)*(d_a(2)*x11 - d_b(2)*x10) - &
                  v_a(3)*(d_a(3)*x11 - d_b(3)*x10) - v_b(1)*(-g_a(0)*x5*x7 + x0*x12) - &
                  v_b(2)*(-d_a(2)*x10 + d_b(2)*x13) - v_b(3)*(-d_a(3)*x10 + d_b(3)*x13))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
               real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
               real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
               real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
               real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
               real(wp) :: x92, x93

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + fj1)
               g_a(2) = &
                  fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_b(0) = fj0
               g_b(1) = a2*fj0 + fj1
               g_b(2) = &
                  (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
                  fp2*fsp2)
               x0 = 1.0_wp/R_a
               x1 = 1.0_wp/R_b
               x2 = x0*x1
               x3 = c_par*g_a(0)*g_b(0)
               x4 = d_a(1)*d_b(1)
               x5 = d_a(2)*d_b(2)
               x6 = d_a(3)*d_b(3)
               x7 = -x2*(x4 + x5 + x6) + 1.0_wp
               x8 = (x7*x7*x7)
               x9 = 4.0_wp*x8
               x10 = x2*x3*x9
               x11 = (d_a(1)*d_a(1))
               x12 = (d_a(2)*d_a(2))
               x13 = (d_a(3)*d_a(3))
               x14 = x11 + x12 + x13
               x15 = 1.0_wp/sqrt(x14)
               x16 = g_a(1)*x15
               x17 = (x7*x7*x7*x7)
               x18 = c_par*x17
               x19 = g_b(0)*x18
               x20 = x0*x19
               x21 = x16*x20
               x22 = (d_b(1)*d_b(1))
               x23 = (d_b(2)*d_b(2))
               x24 = (d_b(3)*d_b(3))
               x25 = x22 + x23 + x24
               x26 = 1.0_wp/sqrt(x25)
               x27 = g_b(1)*x26
               x28 = g_a(0)*x18
               x29 = x1*x28
               x30 = x27*x29
               x31 = 1.0_wp/(R_b*R_b)
               x32 = 1.0_wp/(R_a*R_a)
               x33 = (x7*x7)
               x34 = 12.0_wp*x3*x33
               x35 = x32*x34
               x36 = x31*x35
               x37 = d_a(1)*x36
               x38 = x16*x18*x2*x27
               x39 = d_a(2)*d_b(1)
               x40 = d_a(1)*d_a(2)
               x41 = c_par*x9
               x42 = g_b(0)*x1*x16
               x43 = x41*x42
               x44 = x32*x43
               x45 = d_b(1)*d_b(2)
               x46 = g_a(0)*x0*x27
               x47 = x41*x46
               x48 = x31*x47
               x49 = -x40*x44 - x45*x48
               x50 = d_b(2)*x37 + x38*x39 + x49
               x51 = d_a(3)*d_b(1)
               x52 = d_a(1)*d_a(3)
