               v_a(2)*(x1004*x1379 - x127*x1380 + x1378*x522 - x1379*x671 + x1380*x245 - &
               x1381*x490 + x1381*x495 + x1382*x14 - x1383*x1384 - x1385*x1386 - x1387*x1388 - &
               x1387*x1390 - x1389*x252 + x1389*x254 + x1391*x1392 + x1393*x1394 + 6.0_wp*x353 + &
               x521) - v_a(3)*x1413 - v_a(3)*x1432 - v_b(1)*x1143 - v_b(1)*x1164 - v_b(2)*x1428 - &
               v_b(2)*(x1025*x1378 - x1028*x1378 + x1379*x522 - x1383*x1399 - x1383*x479*x545 - &
