               x1396*x531 + x1397*x9 - x1398*x338*x9 + x1400*x547 + x1401*x549 + 6.0_wp*x363 + &
               x550) - v_b(3)*x1423 - v_b(3)*x1435 - x1236*x669 - x1238*x670 - x1243*x670 - &
               x1247*x669 - x1426*x779 - x1428*x752 - x1437*x752 - x1437*x779 - x1441*x762 - &
               x1444*x786 - x1447*x762 - x1452*x786)
            t_tg3_rrr_112 = &
               -v_a(1)*x1180 - v_a(1)*x1229 - v_a(1)*x1231 - v_a(1)*x1255 - v_a(2)*x1423 - &
               v_a(2)*x1432 - v_a(2)*x1441 - v_a(2)*x1452 - v_a(3)*x1464 - v_a(3)*x1473 - &
               v_a(3)*x1476 - v_a(3)*x1479 - v_b(1)*x1192 - v_b(1)*x1210 - v_b(1)*x1224 - &
               v_b(1)*x1256 - v_b(2)*x1413 - v_b(2)*x1435 - v_b(2)*x1444 - v_b(2)*x1447 - &
               v_b(3)*x1469 - v_b(3)*x1474 - v_b(3)*x1476 - v_b(3)*x1479 - x1250*x217 - x1251*x216 &
               - x1253*x216 - x1254*x217 - x1441*x238 - x1444*x228 - x1447*x228 - x1452*x238 - &
               x1480*x231 - x1481*x241 - x1483*x231 - x1483*x241
            tg3_rrr(2, 2, 3) = tg3_rrr(2, 2, 3) + t_tg3_rrr_112
            tg3_rrr(2, 3, 2) = tg3_rrr(2, 3, 2) + t_tg3_rrr_112
            tg3_rrr(3, 2, 2) = tg3_rrr(3, 2, 2) + t_tg3_rrr_112
            t_tg3_rrr_122 = &
               -v_a(1)*x1283 - v_a(1)*x1300 - v_a(1)*x1321 - v_a(1)*x1338 - v_a(2)*x1469 - &
               v_a(2)*x1473 - v_a(2)*x1480 - v_a(2)*x1481 - v_a(3)*x1493 - v_a(3)*x1502 - &
               v_a(3)*x1505 - v_a(3)*x1507 - v_b(1)*x1271 - v_b(1)*x1303 - v_b(1)*x1325 - &
               v_b(1)*x1343 - v_b(2)*x1464 - v_b(2)*x1474 - v_b(2)*x1480 - v_b(2)*x1481 - &
               v_b(3)*x1499 - v_b(3)*x1503 - v_b(3)*x1506 - v_b(3)*x1508 - x1331*x216 - x1332*x217 &
               - x1334*x216 - x1335*x217 - x1476*x228 - x1479*x238 - x1483*x228 - x1483*x238 - &
               x1505*x241 - x1506*x231 - x1507*x241 - x1508*x231
            tg3_rrr(2, 3, 3) = tg3_rrr(2, 3, 3) + t_tg3_rrr_122
            tg3_rrr(3, 2, 3) = tg3_rrr(3, 2, 3) + t_tg3_rrr_122
            tg3_rrr(3, 3, 2) = tg3_rrr(3, 3, 2) + t_tg3_rrr_122
            tg3_rrr(3, 3, 3) = &
               tg3_rrr(3, 3, 3) + (-v_a(1)*x1362 - v_a(1)*x1366 - v_a(2)*x1499 - v_a(2)*x1502 - &
               v_a(3)*x1524 - v_a(3)*(x1004*x1510 - x127*x1511 + x1382*x15 - x1384*x1513 - &
               x1385*x1514 - x1388*x1515 - x1390*x1515 + x1392*x1517 + x1394*x1518 + x1509*x522 - &
               x1510*x671 + x1511*x245 - x1512*x490 + x1512*x495 - x1516*x252 + x1516*x254 + &
               6.0_wp*x411 + x521) - v_b(1)*x1354 - v_b(1)*x1369 - v_b(2)*x1493 - v_b(2)*x1503 - &
               v_b(3)*x1526 - v_b(3)*(x10*x1397 - x10*x1398*x399 + x1025*x1509 - x1028*x1509 - &
               x1399*x1513 - x150*x1519 + x1510*x522 - x1513*x479*x545 - x1516*x273 + x1516*x275 - &
               x1517*x537 + x1519*x267 - x1520*x526 + x1520*x531 + x1521*x547 + x1522*x549 + &
               6.0_wp*x420 + x550) - x1373*x669 - x1374*x670 - x1376*x670 - x1377*x669 - &
               x1505*x752 - x1506*x779 - x1507*x779 - x1508*x752 - x1524*x786 - x1526*x762 - &
               x1527*x762 - x1527*x786)
         end block
      end select

   end subroutine cfc_pair_tangent_eval

   pure module subroutine cfc_atomic_radius_tangent_eval(d_a, R_a, a1, fade_start, fade_width, vr_a, &
                                                  max_deriv, tg0, tg1_r, tg2_rr, tg3_rrr)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Radius direction of atom a
      real(wp), intent(in) :: vr_a
      !> Highest spatial-derivative order to accumulate (0..3); a larger value is treated as 3
      integer, intent(in) :: max_deriv
      !> sum_A vr_A d/dR_A of the order-0 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg0
      !> sum_A vr_A d/dR_A of the order-1 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg1_r(3)
      !> sum_A vr_A d/dR_A of the order-2 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg2_rr(3, 3)
      !> sum_A vr_A d/dR_A of the order-3 spatial derivative, *added* to the position half
      !> accumulated by the tangent/HVP routines
      real(wp), intent(inout) :: tg3_rrr(3, 3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a1 sigma_a)
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, e_a = w_a exp(a1 sigma_a)
      real(wp) :: e_a(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      if (sg_a > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_atomic_radius_tangent_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5))
               tg0 = &
                  tg0 + (-e_a(1)*vr_a*sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + &
                  (d_a(3)*d_a(3))))/(R_a*R_a))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = &
                  fu*((a1*a1)*fj0 + 2.0_wp*a1*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               x0 = sqrt(((d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))))
               x1 = e_a(1)/(R_a*R_a)
               x2 = e_a(2)/(R_a*R_a*R_a)
               x3 = x1/x0
               tg0 = tg0 + (-vr_a*x0*x1)
               tg1_r(1) = tg1_r(1) + (vr_a*(-d_a(1)*x2 - d_a(1)*x3))
               tg1_r(2) = tg1_r(2) + (vr_a*(-d_a(2)*x2 - d_a(2)*x3))
               tg1_r(3) = tg1_r(3) + (vr_a*(-d_a(3)*x2 - d_a(3)*x3))
            end block
         case (2)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, t_tg2_rr_01, t_tg2_rr_02, t_tg2_rr_12

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fp3 = -1680.0_wp*ft - 210.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               fj2 = (a1*a1)
               fj3 = fp2*fsp2
               fj4 = fp1*fs
               fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = fu*(2.0_wp*a1*fj1 + fj0*fj2 + fj5)
               e_a(3) = &
                  fu*((a1*a1*a1)*fj0 + 3.0_wp*a1*fj5 + (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + &
                  60.0_wp*fj4 + 60.0_wp*fp0 + fp3*fsp3) + 3.0_wp*fj1*fj2)
               x0 = (d_a(1)*d_a(1))
               x1 = (d_a(2)*d_a(2))
               x2 = (d_a(3)*d_a(3))
               x3 = x0 + x1 + x2
               x4 = sqrt(x3)
               x5 = 1.0_wp/(R_a*R_a)
               x6 = e_a(1)*x5
               x7 = e_a(2)/(R_a*R_a*R_a)
               x8 = d_a(1)*x7
               x9 = 1.0_wp/x4
               x10 = x6*x9
               x11 = d_a(2)*x7
               x12 = 1.0_wp/x3
               x13 = x12*x7
               x14 = e_a(3)*x9/(R_a*R_a*R_a*R_a)
               x15 = 1.0_wp/(x3*sqrt(x3))
               x16 = x10 + x7
               x17 = x12*x8
               tg0 = tg0 + (-vr_a*x4*x6)
               tg1_r(1) = tg1_r(1) + (vr_a*(-d_a(1)*x10 - x8))
               tg1_r(2) = tg1_r(2) + (vr_a*(-d_a(2)*x10 - x11))
               tg1_r(3) = tg1_r(3) + (vr_a*(-d_a(3)*x10 - d_a(3)*x7))
               tg2_rr(1, 1) = tg2_rr(1, 1) + (vr_a*(e_a(1)*x0*x15*x5 - x0*x13 - x0*x14 - x16))
               t_tg2_rr_01 = vr_a*(d_a(1)*d_a(2)*e_a(1)*x15*x5 - d_a(1)*d_a(2)*x14 - d_a(2)*x17)
               tg2_rr(1, 2) = tg2_rr(1, 2) + t_tg2_rr_01
               tg2_rr(2, 1) = tg2_rr(2, 1) + t_tg2_rr_01
               t_tg2_rr_02 = vr_a*(d_a(1)*d_a(3)*e_a(1)*x15*x5 - d_a(1)*d_a(3)*x14 - d_a(3)*x17)
               tg2_rr(1, 3) = tg2_rr(1, 3) + t_tg2_rr_02
               tg2_rr(3, 1) = tg2_rr(3, 1) + t_tg2_rr_02
               tg2_rr(2, 2) = tg2_rr(2, 2) + (vr_a*(e_a(1)*x1*x15*x5 - x1*x13 - x1*x14 - x16))
